<?php
namespace app\controller;
use app\BaseController;use app\service\AdminAccess;use app\service\AlipayService;use think\facade\Db;use think\facade\Session;
class RefundAdmin extends BaseController{
 private function guard(){return AdminAccess::guard();}
 private function sig(array $u):string{$secret=trim((string)@file_get_contents((string)(getenv('LUMEN_INTEGRITY_KEY_FILE')?:'/www/server/lumenapi/integrity.key')));return hash_hmac('sha256',$u['id'].'|'.($u['quota_total']===null?'NULL':$u['quota_total']).'|'.$u['quota_used'],$secret);}
 private function validQuotaSignature(array $u):bool{return empty($u['integrity_locked'])&&!empty($u['quota_integrity_hash'])&&hash_equals((string)$u['quota_integrity_hash'],$this->sig($u));}
 private function audit(string $a,int $id,string $d=''){Db::name('audit_logs')->insert(['admin_id'=>Session::get('lumen_admin_id'),'action'=>$a,'target_type'=>'refund','target_id'=>$id,'detail'=>$d,'ip'=>request()->ip(),'created_at'=>date('Y-m-d H:i:s')]);}
 private function restore(int $rid,string $reason):void{Db::transaction(function()use($rid,$reason){$r=Db::name('refund_orders')->where('id',$rid)->lock(true)->find();if(!$r||$r['status']!=='provider_rejected')return;$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$r['recharge_order_id'])->lock(true)->find();$u=Db::name('users')->where('id',$r['user_id'])->lock(true)->find();if(!$lot||!$u||$u['quota_total']===null)throw new \RuntimeException('refund_restore_state');if(!$this->validQuotaSignature($u))throw new \RuntimeException('refund_integrity_invalid');$add=(int)$r['quota_to_recover']+(int)$r['bonus_to_recover'];$total=(int)$u['quota_total']+$add;$sig=$this->sig(['id'=>$u['id'],'quota_total'=>$total,'quota_used'=>$u['quota_used']]);$now=date('Y-m-d H:i:s');Db::name('users')->where('id',$u['id'])->update(['quota_total'=>$total,'trusted_quota_total'=>$total,'trusted_quota_used'=>$u['quota_used'],'quota_integrity_hash'=>$sig,'updated_at'=>$now]);Db::name('keys')->where('user_id',$u['id'])->update(['quota_total'=>$total,'quota_used'=>(int)$u['quota_used'],'updated_at'=>$now]);Db::name('quota_lots')->where('id',$lot['id'])->update(['paid_remaining'=>$r['quota_to_recover'],'bonus_remaining'=>$r['bonus_to_recover'],'status'=>'active','updated_at'=>$now]);Db::name('refund_orders')->where('id',$rid)->update(['status'=>'failed','failure_reason'=>$reason,'updated_at'=>$now]);});}
 private function succeed(int $rid,string $hash=''):void{Db::transaction(function()use($rid,$hash){$r=Db::name('refund_orders')->where('id',$rid)->lock(true)->find();if(!$r||$r['status']==='succeeded')return;if(!in_array($r['status'],['provider_processing','needs_reconcile'],true))throw new \RuntimeException('refund_state');$o=Db::name('recharge_orders')->where('id',$r['recharge_order_id'])->lock(true)->find();$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$r['recharge_order_id'])->lock(true)->find();$u=Db::name('users')->where('id',$r['user_id'])->lock(true)->find();if(!$o||!$lot||!$u)throw new \RuntimeException('refund_finalize_state');$now=date('Y-m-d H:i:s');Db::name('refund_orders')->where('id',$rid)->update(['status'=>'succeeded','provider_response_hash'=>$hash?:$r['provider_response_hash'],'failure_reason'=>null,'succeeded_at'=>$now,'updated_at'=>$now]);Db::name('quota_lots')->where('id',$lot['id'])->update(['status'=>'refunded','updated_at'=>$now]);Db::name('recharge_orders')->where('id',$o['id'])->update(['refund_amount_cents'=>(int)$o['refund_amount_cents']+(int)$r['amount_cents'],'refunded_quota'=>(int)$o['refunded_quota']+(int)$r['quota_to_recover'],'updated_at'=>$now]);$after=$u['quota_total']===null?null:max(0,(int)$u['quota_total']-(int)$u['quota_used']);$before=$after===null?null:$after+(int)$r['quota_to_recover']+(int)$r['bonus_to_recover'];Db::name('quota_ledger')->insert(['user_id'=>$u['id'],'direction'=>'out','amount'=>(int)$r['quota_to_recover']+(int)$r['bonus_to_recover'],'source_type'=>'refund','source_id'=>$r['id'],'request_id'=>$r['refund_no'],'balance_before'=>$before,'balance_after'=>$after,'remark'=>'支付宝退款成功；付费额度与关联赠送额度回收','created_at'=>$now]);});}
 public function approve($id){if($g=$this->guard())return$g;$r=Db::name('refund_orders')->where('id',(int)$id)->where('request_source','user')->where('status','requested')->find();if(!$r)return response('退款申请不存在或已处理',422);Db::name('refund_orders')->where('id',$r['id'])->update(['status'=>'cancelled','failure_reason'=>'管理员审核通过，转为执行退款','reviewed_by'=>Session::get('lumen_admin_id'),'reviewed_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$this->audit('refund.approve',$r['id'],'user_request');return $this->create($r['recharge_order_id']);}
 public function reject($id){if($g=$this->guard())return$g;$reason=mb_substr(trim((string)input('post.reason','')),0,500);if($reason==='')return response('拒绝原因必填',422);$r=Db::name('refund_orders')->where('id',(int)$id)->where('request_source','user')->where('status','requested')->find();if(!$r)return response('退款申请不存在或已处理',422);Db::name('refund_orders')->where('id',$r['id'])->update(['status'=>'rejected','failure_reason'=>$reason,'reviewed_by'=>Session::get('lumen_admin_id'),'reviewed_at'=>date('Y-m-d H:i:s'),'updated_at'=>date('Y-m-d H:i:s')]);$this->audit('refund.reject',$r['id'],$reason);return redirect('/admin/payments?refund=rejected_by_admin');}
 public function create($id){if($g=$this->guard())return$g;$id=(int)$id;$rid=0;$refundNo='';$orderNo='';$amount=0;
  try{Db::transaction(function()use($id,&$rid,&$refundNo,&$orderNo,&$amount){$o=Db::name('recharge_orders')->where('id',$id)->lock(true)->find();if(!$o||$o['status']!=='credited'||empty($o['provider_trade_no']))throw new \RuntimeException('订单不可退款');if(Db::name('refund_orders')->where('recharge_order_id',$id)->whereIn('status',['created','provider_processing','needs_reconcile'])->find())throw new \RuntimeException('该订单已有退款处理中');$lot=Db::name('quota_lots')->where('source_type','recharge')->where('source_id',$id)->lock(true)->find();if(!$lot||!(int)$lot['refundable']||(int)$lot['paid_quota']<=0||(int)$lot['paid_remaining']<=0)throw new \RuntimeException('当前无可退付费额度');$u=Db::name('users')->where('id',$o['user_id'])->lock(true)->find();if(!$u||$u['quota_total']===null||!$this->validQuotaSignature($u))throw new \RuntimeException('账户额度完整性异常，不允许退款');$paidRemain=(int)$lot['paid_remaining'];$bonusRemain=(int)$lot['bonus_remaining'];$amount=intdiv((int)$lot['paid_amount_cents']*$paidRemain,(int)$lot['paid_quota']);$amount=min($amount,max(0,(int)$o['amount_cents']-(int)$o['refund_amount_cents']));if($amount<=0)throw new \RuntimeException('可退款金额不足 0.01 元');$recover=$paidRemain+$bonusRemain;$avail=max(0,(int)$u['quota_total']-(int)$u['quota_used']);if($avail<$recover)throw new \RuntimeException('额度批次与账户余额不一致，已拒绝退款');$refundNo='RF'.date('YmdHis').strtoupper(bin2hex(random_bytes(5)));$orderNo=$o['order_no'];$now=date('Y-m-d H:i:s');$newTotal=(int)$u['quota_total']-$recover;$sig=$this->sig(['id'=>$u['id'],'quota_total'=>$newTotal,'quota_used'=>$u['quota_used']]);$rid=Db::name('refund_orders')->insertGetId(['refund_no'=>$refundNo,'recharge_order_id'=>$id,'user_id'=>$u['id'],'provider'=>'alipay','provider_trade_no'=>$o['provider_trade_no'],'amount_cents'=>$amount,'quota_to_recover'=>$paidRemain,'bonus_to_recover'=>$bonusRemain,'status'=>'provider_processing','requested_by'=>Session::get('lumen_admin_id'),'created_at'=>$now,'updated_at'=>$now]);Db::name('quota_lots')->where('id',$lot['id'])->update(['paid_remaining'=>0,'bonus_remaining'=>0,'status'=>'refund_pending','updated_at'=>$now]);Db::name('users')->where('id',$u['id'])->update(['quota_total'=>$newTotal,'trusted_quota_total'=>$newTotal,'trusted_quota_used'=>$u['quota_used'],'quota_integrity_hash'=>$sig,'updated_at'=>$now]);Db::name('keys')->where('user_id',$u['id'])->update(['quota_total'=>$newTotal,'quota_used'=>(int)$u['quota_used'],'updated_at'=>$now]);});}catch(\Throwable $e){return response($e->getMessage(),422);}
  return $this->sendProvider($rid,$orderNo,$amount,$refundNo);
 }
 private function sendProvider(int $rid,string $orderNo,int $amount,string $refundNo){$this->audit('refund.request',$rid,'order='.$orderNo.'; cents='.$amount);try{$raw=AlipayService::refund($orderNo,$amount,$refundNo);$resp=$raw['alipay_trade_refund_response']??[];$hash=hash('sha256',json_encode($raw,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if((string)($resp['code']??'')==='10000'){$this->succeed($rid,$hash);$this->audit('refund.succeeded',$rid,'signature_verified');return redirect('/admin/payments?refund=success');}Db::name('refund_orders')->where('id',$rid)->update(['status'=>'provider_rejected','provider_response_hash'=>$hash,'failure_reason'=>mb_substr((string)($resp['sub_msg']??$resp['msg']??'provider_rejected'),0,255),'updated_at'=>date('Y-m-d H:i:s')]);$this->restore($rid,'支付宝明确拒绝退款');$this->audit('refund.rejected',$rid,'signed provider rejection');return redirect('/admin/payments?refund=rejected');}catch(\Throwable $e){Db::name('refund_orders')->where('id',$rid)->update(['status'=>'needs_reconcile','failure_reason'=>mb_substr($e->getMessage(),0,255),'updated_at'=>date('Y-m-d H:i:s')]);$this->audit('refund.needs_reconcile',$rid,$e->getMessage());return redirect('/admin/payments?refund=reconcile');}}
 public function reconcile($id){if($g=$this->guard())return$g;$r=Db::name('refund_orders')->where('id',(int)$id)->find();if(!$r||!in_array($r['status'],['needs_reconcile','provider_processing'],true))return response('退款单当前无需对账',422);$o=Db::name('recharge_orders')->where('id',$r['recharge_order_id'])->find();if(!$o)return response('原订单不存在',404);try{$raw=AlipayService::refundQuery($o['order_no'],$r['refund_no']);$resp=$raw['alipay_trade_fastpay_refund_query_response']??[];$hash=hash('sha256',json_encode($raw,JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES));if((string)($resp['code']??'')==='10000'&&(string)($resp['refund_status']??'')==='REFUND_SUCCESS'){$this->succeed((int)$r['id'],$hash);$this->audit('refund.reconciled',$r['id'],'REFUND_SUCCESS');return redirect('/admin/payments?refund=success');}Db::name('refund_orders')->where('id',$r['id'])->update(['provider_response_hash'=>$hash,'failure_reason'=>'对账未确认退款成功','updated_at'=>date('Y-m-d H:i:s')]);return redirect('/admin/payments?refund=pending');}catch(\Throwable $e){Db::name('refund_orders')->where('id',$r['id'])->update(['failure_reason'=>mb_substr($e->getMessage(),0,255),'updated_at'=>date('Y-m-d H:i:s')]);return redirect('/admin/payments?refund=reconcile');}}
}
